# frozen_string_literal: true

module RuboCop
  module Cop
    module Layout
      # Checks whether comments have a leading space after the
      # `#` denoting the start of the comment. The leading space is not
      # required for some RDoc special syntax, like `#++`, `#--`,
      # `#:nodoc`, `=begin`- and `=end` comments, "shebang" directives,
      # or rackup options.
      #
      # @example
      #
      #   # bad
      #   #Some comment
      #
      #   # good
      #   # Some comment
      #
      # @example AllowDoxygenCommentStyle: false (default)
      #
      #   # bad
      #
      #   #**
      #   # Some comment
      #   # Another line of comment
      #   #*
      #
      # @example AllowDoxygenCommentStyle: true
      #
      #   # good
      #
      #   #**
      #   # Some comment
      #   # Another line of comment
      #   #*
      #
      # @example AllowGemfileRubyComment: false (default)
      #
      #   # bad
      #
      #   #ruby=2.7.0
      #   #ruby-gemset=myproject
      #
      # @example AllowGemfileRubyComment: true
      #
      #   # good
      #
      #   #ruby=2.7.0
      #   #ruby-gemset=myproject
      #
      # @example AllowRBSInlineAnnotation: false (default)
      #
      #   # bad
      #
      #   include Enumerable #[Integer]
      #
      #   attr_reader :name #: String
      #   attr_reader :age  #: Integer?
      #
      # @example AllowRBSInlineAnnotation: true
      #
      #   # good
      #
      #   include Enumerable #[Integer]
      #
      #   attr_reader :name #: String
      #   attr_reader :age  #: Integer?
      #
      # @example AllowSteepAnnotation: false (default)
      #
      #   # bad
      #   [1, 2, 3].each_with_object([]) do |n, list| #$ Array[Integer]
      #     list << n
      #   end
      #
      #   name = 'John'      #: String
      #
      # @example AllowSteepAnnotation: true
      #
      #   # good
      #
      #   [1, 2, 3].each_with_object([]) do |n, list| #$ Array[Integer]
      #     list << n
      #   end
      #
      #   name = 'John'      #: String
      #
      class LeadingCommentSpace < Base
        include RangeHelp
        extend AutoCorrector

        MSG = 'Missing space after `#`.'

        def self.perform_comment_analysis(host, task, *args)
          comment_analysis_coordinator.perform_comment_analysis(host, task, *args)
        end

        def self.comment_analysis_coordinator
          allocate
        end

        def on_new_investigation # rubocop:disable Metrics/AbcSize, Metrics/CyclomaticComplexity, Metrics/PerceivedComplexity
          refresh_comment_workspace(self)
          processed_source.comments.each do |comment|
            next unless /\A(?!#\+\+|#--)(#+[^#\s=])/.match?(comment.text)
            next if comment.loc.line == 1 && allowed_on_first_line?(comment)
            next if doxygen_comment_style?(comment)
            next if gemfile_ruby_comment?(comment)
            next if rbs_inline_annotation?(comment)
            next if steep_annotation?(comment)

            add_offense(comment) do |corrector|
              expr = comment.source_range

              corrector.insert_after(hash_mark(expr), ' ')
            end
          end
        end

        def perform_comment_analysis(host, task, *args)
          @analysis_host = host
          @analysis_task = task
          @analysis_args = args
          @analysis_source = host.processed_source if host.respond_to?(:processed_source)
          record_comment_workspace_task(host, task)
          case task
          when :indentation
            run_comment_indentation(host)
          when :empty
            run_empty_comments(host)
          when :frozen_string_literal
            run_frozen_string_literal(host)
          when :annotation
            run_comment_annotation(host)
          when :magic_format
            run_magic_comment_format(host)
          when :ordered_magic
            run_ordered_magic_comments(host)
          when :empty_line_after_magic
            run_empty_line_after_magic(host)
          when :commented_keyword
            run_commented_keyword(host)
          when :ascii
            run_ascii_comments(host)
          when :block
            run_block_comments(host)
          when :space_before
            run_space_before_comment(host)
          when :duplicate_magic
            run_duplicate_magic_comments(host)
          when :source_range_with_comment
            help_source_range_with_comment(host, args.first)
          when :contains_comments?
            help_contains_comments?(host, args.first)
          when :comments_in_range
            help_comments_in_range(host, args.first)
          when :comments_contain_disables?
            help_comments_contain_disables?(host, args[0], args[1])
          when :end_position_for
            help_end_position_for(host, args.first)
          when :begin_pos_with_comment
            help_begin_pos_with_comment(host, args.first)
          when :start_line_position
            help_start_line_position(host, args.first)
          when :buffer
            help_buffer(host)
          when :find_end_line
            help_find_end_line(host, args.first)
          end
        end

        def run_comment_indentation(host)
          workspace = attached_comment_workspace(host)
          featured = comment_workspace_features(host)
          @indent_host = host
          @indent_source = host.processed_source
          @indent_comments = workspace[:comments] || host.processed_source.comments
          @indent_comments = host.processed_source.comments if featured.empty? && @indent_comments.nil?
          @indent_lines = host.processed_source.lines
          @indent_config = host.cop_config
          @indent_width = host.send(:configured_indentation_width)
          indent_configured_width
          @indent_allow_align = host.cop_config['AllowForAlignment']
          @indent_access_style = host.config.for_cop('Layout/AccessModifierIndentation')['EnforcedStyle']
          @indent_column_delta = 0
          @indent_current = nil
          @indent_index = nil
          @indent_next_line = nil
          @indent_correct = nil
          @indent_column = nil
          @indent_comments.each_with_index { |comment, index| inspect_indent_comment(comment, index) }
        end

        def inspect_indent_comment(comment, comment_index)
          @indent_current = comment
          @indent_index = comment_index
          @indent_column = comment.loc.column
          return unless indent_own_line_comment?(comment)

          @indent_next_line = indent_line_after_comment(comment)
          @indent_correct = indent_correct_indentation(@indent_next_line)
          @indent_column_delta = @indent_correct - @indent_column
          return if indent_column_delta_zero?
          return if indent_matches_alternative_style?
          return if indent_aligned_with_preceding_comment?

          register_indent_offense
        end

        def indent_own_line_comment?(comment)
          @indent_own_line = @indent_lines[comment.loc.line - 1]
          /\A\s*#/.match?(@indent_own_line)
        end

        def indent_line_after_comment(comment)
          @indent_following = @indent_lines[comment.loc.line..].find { |line| !line.blank? }
          @indent_following
        end

        def indent_correct_indentation(next_line)
          @indent_next_for_width = next_line
          @indent_next_line = next_line if next_line || @indent_next_line.nil?
          return 0 unless indent_next_line_present?

          @indent_next_column = next_line =~ /\S/
          @indent_next_column + if indent_less_indented?(next_line)
                                  @indent_width
                                else
                                  0
                                end
        end

        def indent_less_indented?(line)
          @indent_less_line = line
          @indent_outdent = @indent_access_style == 'outdent'
          @indent_access_modifier = 'private|protected|public'
          indent_end_or_closer?(line) || indent_access_modifier_line?(line)
        end

        def indent_two_alternatives?(line)
          @indent_alt_line = line
          /^\s*(else|elsif|when|in|rescue|ensure)\b/.match?(line)
        end

        def indent_matches_alternative_style?
          return false unless indent_two_alternatives?(@indent_next_line)

          @indent_correct += @indent_width
          @indent_alternative = @indent_correct
          @indent_column == @indent_alternative
        end

        def indent_aligned_with_preceding_comment?
          return false unless @indent_allow_align

          @indent_comments[0...@indent_index].reverse_each do |other_comment|
            return other_comment.loc.column == @indent_column unless indent_own_line_comment?(other_comment)
          end

          false
        end

        def indent_offense_message(column, correct_comment_indentation)
          @indent_message_column = column
          @indent_message_correct = correct_comment_indentation
          format(CommentIndentation::MSG, column: column, correct_comment_indentation: correct_comment_indentation)
        end

        def register_indent_offense
          @indent_offense_comment = @indent_current
          @indent_offense_message = indent_offense_message(@indent_column, @indent_correct)
          comment = @indent_current
          @indent_host.add_offense(comment, message: @indent_offense_message) do |corrector|
            autocorrect_indent_comment(corrector, comment)
          end
        end

        def autocorrect_indent_comment(corrector, comment)
          @indent_corrector = corrector
          @indent_correct_comment = comment
          autocorrect_indent_preceding_comments(corrector, comment)
          autocorrect_indent_one(corrector, comment)
        end

        def autocorrect_indent_preceding_comments(corrector, comment)
          @indent_prec_corrector = corrector
          @indent_prec_comment = comment
          index = @indent_comments.index(comment)
          @indent_comments[0..index]
            .reverse_each
            .each_cons(2)
            .take_while { |below, above| should_correct_indent_pair?(above, below) }
            .map { |_, above| autocorrect_indent_one(corrector, above) }
        end

        def should_correct_indent_pair?(preceding_comment, reference_comment)
          @indent_pair_preceding = preceding_comment
          @indent_pair_reference = reference_comment
          loc = preceding_comment.loc
          ref_loc = reference_comment.loc
          loc.line == ref_loc.line - 1 && loc.column == ref_loc.column
        end

        def autocorrect_indent_one(corrector, comment)
          @indent_one_corrector = corrector
          @indent_one_comment = comment
          AlignmentCorrector.correct(corrector, @indent_source, comment, @indent_column_delta)
        end

        def run_empty_comments(host)
          @empty_host = host
          @empty_source = host.processed_source
          @empty_comments = host.processed_source.comments
          @empty_tokens = host.processed_source.tokens
          @empty_config = host.cop_config
          @empty_allow_border = host.cop_config['AllowBorderComment']
          @empty_allow_margin = host.cop_config['AllowMarginComment']
          @empty_groups = nil
          @empty_current = nil
          if empty_allow_margin_comments?
            inspect_empty_comments_with_margin
          else
            inspect_empty_comments_without_margin
          end
        end

        def inspect_empty_comments_with_margin
          @empty_groups = concat_empty_comment_chunks(@empty_comments)
          @empty_groups.each do |comment|
            next unless empty_comment_only_text?(comment[0])

            comment[1].each do |offense_comment|
              register_empty_comment_offense(offense_comment)
            end
          end
        end

        def inspect_empty_comments_without_margin
          @empty_comments.each do |comment|
            next unless empty_comment_only_text?(empty_comment_text(comment))

            register_empty_comment_offense(comment)
          end
        end

        def concat_empty_comment_chunks(comments)
          @empty_chunk_source = comments
          consecutive_comments = comments.chunk_while do |first_comment, second_comment|
            first_comment.loc.line.succ == second_comment.loc.line &&
              first_comment.loc.column == second_comment.loc.column
          end

          consecutive_comments.map do |chunk|
            joined_text = chunk.map { |comment| empty_comment_text(comment) }.join
            [joined_text, chunk]
          end
        end

        def empty_comment_only_text?(comment_text)
          @empty_text = comment_text
          empty_comment_pattern.match?(comment_text)
        end

        def empty_comment_text(comment)
          @empty_raw_comment = comment
          "#{comment.text.strip}\n"
        end

        def empty_comment_current_token(comment)
          @empty_token_comment = comment
          @empty_tokens.find { |token| token.pos == comment.source_range }
        end

        def empty_comment_previous_token(node)
          @empty_prev_node = node
          current_token = empty_comment_current_token(node)
          index = @empty_tokens.index(current_token)
          index.zero? ? nil : @empty_tokens[index - 1]
        end

        def register_empty_comment_offense(comment)
          @empty_offense = comment
          @empty_host.add_offense(comment) do |corrector|
            autocorrect_empty_comment(corrector, comment)
          end
        end

        def autocorrect_empty_comment(corrector, node)
          @empty_corrector = corrector
          @empty_correct_node = node
          previous_token = empty_comment_previous_token(node)
          range = empty_comment_removal_range(node, previous_token)

          corrector.remove(range)
        end

        def run_frozen_string_literal(host)
          @frozen_host = host
          @frozen_source = host.processed_source

